import { carriesProductToken } from './cms-composition/provider-fault-guard';
import {
  internalError,
  mapCmsEditorialRpcFailure,
} from './cms-editorial-production-errors';
import type { CmsEditorialProductionError } from './cms-editorial-production-types';

/**
 * RPC failure mapping for the CMS-03C production adapters.
 *
 * BE03c 1298-1302: "A response with an unmapped status or a message not generated by its
 * operation catalog is a contract failure and is treated as INTERNAL_ERROR 500 without leaking
 * the original payload." A provider 4xx that carries no product token (PostgREST `PGRST*`, a raw
 * SQLSTATE, an engine `40001` serialization failure, a code-less or non-object body) is such a
 * response: it is answered as the scrubbed 500, never as the 401/403/404/409/422 the HTTP status
 * alone would suggest. Anything else, including every 5xx, takes the shared editorial mapping.
 *
 * `mapCmsEditorialRpcFailure` itself is unchanged: its status fallback is the 03b contract.
 */
export const mapCmsCompositionRpcFailure = (
  status: number,
  payload: unknown,
): CmsEditorialProductionError =>
  status < 500 && !carriesProductToken(payload)
    ? internalError()
    : mapCmsEditorialRpcFailure(status, payload);
